head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getDataDragDrop]<br/>GridView 컴포넌트의 dataDragDrop 속성값을 반환합니다.",
    "validation" : [
        "dataDragDrop 속성의 현재 설정값을 true/false 로 반환합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con_dataDragDrop : 공통 gdl_boolean (getText() 로 '' 미설정 / 'true' / 'false' 판단)
    //  - '' : 속성 자체를 추가하지 않음(기본 false)
    let vDrag = con_dataDragDrop.getText();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="con_dataDragDrop = ' + (vDrag === '' ? '미설정(속성 미부여=기본 false)' : vDrag) + ' 을 grid 에 적용. [getDataDragDrop] 버튼으로 현재 dataDragDrop 속성값(true/false)을 반환받아 출력. 미설정 시 기본 false 반환."', '', 'label1');

    // 속성 적용 : '' 미설정이면 dataDragDrop 속성 자체를 부여하지 않음(기본 false)
    let properties = { dataList: "data:dlt_bind" };
    if (vDrag === 'true') {
        properties.dataDragDrop = true;
    } else if (vDrag === 'false') {
        properties.dataDragDrop = false;
    }

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList);

    scwin.btn_getDataDragDrop_onclick();
}



// getDataDragDrop : 현재 dataDragDrop 속성값(Boolean) 반환 출력
scwin.btn_getDataDragDrop_onclick = function () {
    let rtn = target1.getDataDragDrop();
    wf_body_bottom.getObj("scwin").setReturnValue("getDataDragDrop() : " + rtn);
}
